"use client";

import React from 'react';
import { useUserFeatures } from '@/context/UserFeatureContext';
import { useCart } from '@/context/CartContext';
import { X, ShoppingCart, AlertCircle, ArrowLeft, Star, Package } from 'lucide-react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { API_URL2 } from '@/api/api';

export default function CompareContent() {
    const { compareList, removeFromCompare } = useUserFeatures();
    const { addToCart } = useCart();
    const router = useRouter();

    if (compareList.length === 0) {
        return (
            <div className="min-h-[70vh] flex flex-col items-center justify-center bg-gradient-to-b from-gray-50 to-white px-4">
                <div className="relative">
                    <div className="absolute inset-0 bg-blue-500 opacity-10 blur-3xl rounded-full"></div>
                    <div className="relative w-32 h-32 bg-gradient-to-br from-blue-50 to-indigo-50 rounded-2xl flex items-center justify-center shadow-xl mb-8 border border-blue-100">
                        <Package className="w-16 h-16 text-blue-400" strokeWidth={1.5} />
                    </div>
                </div>
                <h2 className="text-3xl font-bold text-gray-900 mb-3 tracking-tight">No Products to Compare</h2>
                <p className="text-gray-600 mb-10 text-center max-w-md text-lg leading-relaxed">
                    Start comparing products to find the perfect match for your needs.
                </p>
                <Link
                    href="/products"
                    className="group bg-gradient-to-r from-gray-900 to-gray-800 text-white px-10 py-4 rounded-xl font-semibold hover:shadow-2xl hover:scale-105 transition-all duration-300 flex items-center gap-3"
                >
                    Browse Products
                    <ArrowLeft className="w-5 h-5 rotate-180 group-hover:translate-x-1 transition-transform" />
                </Link>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gradient-to-b from-gray-50 to-white">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
                {/* Header Section */}
                <div className="mb-10">
                    <div className="flex items-center gap-4 mb-4">
                        <Link
                            href="/products"
                            className="group p-3 hover:bg-white rounded-xl transition-all duration-300 hover:shadow-lg border border-transparent hover:border-gray-200"
                        >
                            <ArrowLeft className="w-6 h-6 text-gray-600 group-hover:text-gray-900 group-hover:-translate-x-1 transition-all" />
                        </Link>
                        <div>
                            <h1 className="text-4xl font-bold text-gray-900 tracking-tight">Product Comparison</h1>
                            <p className="text-gray-600 mt-1 text-sm font-medium">{compareList.length} {compareList.length === 1 ? 'product' : 'products'} selected</p>
                        </div>
                    </div>
                </div>

                {/* Comparison Table Container */}
                <div className="bg-white rounded-2xl shadow-xl border border-gray-200 overflow-hidden">
                    <div className="overflow-x-auto">
                        <table className="w-full min-w-[900px] border-collapse">
                            <thead className="sticky top-0 z-10">
                                <tr>
                                    <th className="p-6 text-left bg-gradient-to-br from-gray-50 to-gray-100 border-b-2 border-gray-200 min-w-[220px]">
                                        <span className="text-sm font-bold text-gray-700 uppercase tracking-wider">Specifications</span>
                                    </th>
                                    {compareList.map((product, index) => (
                                        <th key={product.id} className="p-6 border-b-2 border-gray-200 min-w-[280px] relative bg-white">
                                            <button
                                                onClick={() => removeFromCompare(product.id!)}
                                                className="absolute top-4 right-4 p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all duration-300 hover:scale-110 hover:shadow-md z-20"
                                                aria-label="Remove from comparison"
                                            >
                                                <X className="w-5 h-5" strokeWidth={2.5} />
                                            </button>

                                            <div className="flex flex-col items-center text-center pt-2">
                                                {/* Product Image */}
                                                <div className="w-36 h-36 mb-5 relative group">
                                                    <div className="absolute inset-0 bg-gradient-to-br from-blue-100 to-indigo-100 rounded-2xl opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
                                                    <img
                                                        src={`${API_URL2}${product.image}`}
                                                        alt={product.title}
                                                        className="w-full h-full object-contain relative z-10 transition-transform duration-300 group-hover:scale-105"
                                                    />
                                                </div>

                                                {/* Product Title */}
                                                <h3 className="font-bold text-gray-900 mb-2 line-clamp-2 h-12 text-base leading-tight px-2">
                                                    {product.title}
                                                </h3>

                                                {/* Price */}
                                                <div className="mb-4">
                                                    <p className="text-2xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-600 to-indigo-600">
                                                        ₹{product.finalPrice.toLocaleString('en-IN')}
                                                    </p>
                                                </div>

                                                {/* Add to Cart Button */}
                                                <button
                                                    onClick={() => addToCart(product)}
                                                    className="w-full bg-gradient-to-r from-blue-600 to-indigo-600 text-white py-3 rounded-xl font-semibold text-sm hover:shadow-xl hover:scale-105 transition-all duration-300 flex items-center justify-center gap-2 group"
                                                >
                                                    <ShoppingCart className="w-4 h-4 group-hover:scale-110 transition-transform" />
                                                    Add to Cart
                                                </button>
                                            </div>
                                        </th>
                                    ))}
                                </tr>
                            </thead>

                            <tbody className="divide-y divide-gray-100">
                                {/* Rating Row */}
                                <tr className="hover:bg-gray-50/50 transition-colors">
                                    <td className="p-5 font-semibold text-gray-800 bg-gradient-to-r from-gray-50 to-transparent">
                                        <div className="flex items-center gap-2">
                                            <Star className="w-4 h-4 text-amber-500 fill-amber-500" />
                                            <span>Rating</span>
                                        </div>
                                    </td>
                                    {compareList.map(product => (
                                        <td key={product.id} className="p-5 text-center">
                                            <div className="flex items-center justify-center gap-2">
                                                <span className="font-bold text-gray-900 text-lg">{product.rating}</span>
                                                <div className="flex">
                                                    {[...Array(5)].map((_, i) => (
                                                        <Star
                                                            key={i}
                                                            className={`w-4 h-4 ${i < Math.floor(product.rating) ? 'text-amber-400 fill-amber-400' : 'text-gray-300'}`}
                                                        />
                                                    ))}
                                                </div>
                                                <span className="text-gray-500 text-sm font-medium">({product.reviews})</span>
                                            </div>
                                        </td>
                                    ))}
                                </tr>

                                {/* Brand Row */}
                                <tr className="hover:bg-gray-50/50 transition-colors">
                                    <td className="p-5 font-semibold text-gray-800 bg-gradient-to-r from-gray-50 to-transparent">Brand</td>
                                    {compareList.map(product => (
                                        <td key={product.id} className="p-5 text-center">
                                            <span className="inline-block px-4 py-1.5 bg-gradient-to-r from-gray-100 to-gray-50 text-gray-700 rounded-lg font-medium text-sm border border-gray-200">
                                                {product.brand}
                                            </span>
                                        </td>
                                    ))}
                                </tr>

                                {/* Processor Row */}
                                <tr className="hover:bg-gray-50/50 transition-colors">
                                    <td className="p-5 font-semibold text-gray-800 bg-gradient-to-r from-gray-50 to-transparent">Processor</td>
                                    {compareList.map(product => (
                                        <td key={product.id} className="p-5 text-center">
                                            <span className="text-gray-700 font-medium text-sm leading-relaxed">{product.specs.processor}</span>
                                        </td>
                                    ))}
                                </tr>

                                {/* RAM Row */}
                                <tr className="hover:bg-gray-50/50 transition-colors">
                                    <td className="p-5 font-semibold text-gray-800 bg-gradient-to-r from-gray-50 to-transparent">RAM</td>
                                    {compareList.map(product => (
                                        <td key={product.id} className="p-5 text-center">
                                            <span className="text-gray-700 font-medium text-sm">{product.specs.ram}</span>
                                        </td>
                                    ))}
                                </tr>

                                {/* Storage Row */}
                                <tr className="hover:bg-gray-50/50 transition-colors">
                                    <td className="p-5 font-semibold text-gray-800 bg-gradient-to-r from-gray-50 to-transparent">Storage</td>
                                    {compareList.map(product => (
                                        <td key={product.id} className="p-5 text-center">
                                            <span className="text-gray-700 font-medium text-sm">{product.specs.storage}</span>
                                        </td>
                                    ))}
                                </tr>

                                {/* Display Row */}
                                <tr className="hover:bg-gray-50/50 transition-colors">
                                    <td className="p-5 font-semibold text-gray-800 bg-gradient-to-r from-gray-50 to-transparent">Display</td>
                                    {compareList.map(product => (
                                        <td key={product.id} className="p-5 text-center">
                                            <span className="text-gray-700 font-medium text-sm leading-relaxed">{product.specs.display}</span>
                                        </td>
                                    ))}
                                </tr>

                                {/* Graphics Row */}
                                <tr className="hover:bg-gray-50/50 transition-colors">
                                    <td className="p-5 font-semibold text-gray-800 bg-gradient-to-r from-gray-50 to-transparent">Graphics</td>
                                    {compareList.map(product => (
                                        <td key={product.id} className="p-5 text-center">
                                            <span className="text-gray-700 font-medium text-sm leading-relaxed">{product.specs.graphics}</span>
                                        </td>
                                    ))}
                                </tr>

                                {/* Condition Row */}
                                <tr className="hover:bg-gray-50/50 transition-colors">
                                    <td className="p-5 font-semibold text-gray-800 bg-gradient-to-r from-gray-50 to-transparent">Condition</td>
                                    {compareList.map(product => (
                                        <td key={product.id} className="p-5 text-center">
                                            <span className="inline-block bg-gradient-to-r from-emerald-500 to-green-500 text-white px-5 py-2 rounded-full text-xs font-bold tracking-wide shadow-lg shadow-green-200 uppercase">
                                                {product.condition || 'Excellent'}
                                            </span>
                                        </td>
                                    ))}
                                </tr>
                            </tbody>
                        </table>
                    </div>
                </div>

                {/* Bottom Spacing */}
                <div className="h-12"></div>
            </div>
        </div>
    );
}